(() => {
  'use strict';

  /* ================= configuration ================= */
  const COLS = 60, ROWS = 60, CELL = 10;   // 60×60 cells → 600×600 px canvas
  const W = COLS * CELL, H = ROWS * CELL;

  const canvas = document.getElementById('life');
  const ctx = canvas.getContext('2d');
  const genEl = document.getElementById('gen');
  const popEl = document.getElementById('pop');
  const playBtn = document.getElementById('play');
  const speedInput = document.getElementById('speed');
  const speedVal = document.getElementById('speedVal');

  /* ================= state ================= */
  let grid = new Uint8Array(COLS * ROWS);  // 0 = dead, 1 = alive
  let age = new Uint8Array(COLS * ROWS);   // generations survived (for colour)
  let generation = 0;
  let playing = false;
  let speed = 12;                          // generations per second
  let hover = null;                        // cell under the pointer

  const idx = (x, y) => y * COLS + x;

  /* ================= palette (newborns pop gold, elders cool to cyan) ================= */
  const AGE_COLORS = [];
  for (let a = 0; a <= 12; a++) {
    const h = a <= 1 ? 47 : a === 2 ? 96 : Math.min(205, 140 + (a - 3) * 8);
    AGE_COLORS.push({
      core: 'hsl(' + h + ', 95%, 64%)',
      glow: 'hsla(' + h + ', 95%, 62%, ' + (a <= 1 ? 0.17 : 0.10) + ')'
    });
  }
  const ageColor = (a) => AGE_COLORS[a > 12 ? 12 : a];

  /* ================= simulation ================= */

  // 8 surrounding neighbours; anything outside the grid counts as dead (no wrap).
  function liveNeighbours(x, y) {
    let n = 0;
    for (let dy = -1; dy <= 1; dy++) {
      const yy = y + dy;
      if (yy < 0 || yy >= ROWS) continue;          // edge = dead
      for (let dx = -1; dx <= 1; dx++) {
