        const xx = x + dx;
        if (xx < 0 || xx >= COLS) continue;        // edge = dead
        n += grid[yy * COLS + xx];
      }
    }
    return n;
  }

  // Advance exactly ONE generation. Every cell's next state is derived from the
  // CURRENT grid into a fresh buffer, then swapped in all at once — cells are
  // never updated in place, so later cells never see already-updated neighbours.
  // Rules: dead + exactly 3 neighbours → born; alive + (2 or 3) → survives; else dies.
  function stepGeneration() {
    const next = new Uint8Array(COLS * ROWS);
    const nextAge = new Uint8Array(COLS * ROWS);
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        const i = y * COLS + x;
        const n = liveNeighbours(x, y);
        if (grid[i]) {
          if (n === 2 || n === 3) {                // survival
            next[i] = 1;
            nextAge[i] = age[i] < 255 ? age[i] + 1 : 255;
          }                                        // otherwise dies (lonely / crowded)
        } else if (n === 3) {                      // birth
          next[i] = 1;
          nextAge[i] = 1;
        }
      }
    }
    grid = next;
    age = nextAge;
    generation++;
    draw();
    updateStats();
  }

  /* ================= rendering ================= */
  function draw() {
    // deep-space background
    ctx.fillStyle = '#0a0e17';
    ctx.fillRect(0, 0, W, H);

    // faint lattice
    ctx.strokeStyle = 'rgba(140, 170, 255, 0.07)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let x = 1; x < COLS; x++) {
      ctx.moveTo(x * CELL + 0.5, 0);
      ctx.lineTo(x * CELL + 0.5, H);
    }
    for (let y = 1; y < ROWS; y++) {
      ctx.moveTo(0, y * CELL + 0.5);
      ctx.lineTo(W, y * CELL + 0.5);
    }
    ctx.stroke();

    // additive bloom pass
    ctx.globalCompositeOperation = 'lighter';
    for (let y = 0; y < ROWS; y++) {
      const row = y * COLS;
      for (let x = 0; x < COLS; x++) {
        if (!grid[row + x]) continue;
        ctx.fillStyle = ageColor(age[row + x]).glow;
        ctx.fillRect(x * CELL - 2, y * CELL - 2, CELL + 4, CELL + 4);
      }
    }
    ctx.globalCompositeOperation = 'source-over';

    // bright cell cores (newborns drawn a touch larger)
    const hasRound = typeof ctx.roundRect === 'function';
    for (let y = 0; y < ROWS; y++) {
      const row = y * COLS;
      for (let x = 0; x < COLS; x++) {
        const i = row + x;
        if (!grid[i]) continue;
        const newborn = age[i] <= 1;
        const inset = newborn ? 0.5 : 1.5;
        const s = CELL - inset * 2;
        ctx.fillStyle = ageColor(age[i]).core;
        ctx.beginPath();
        if (hasRound) ctx.roundRect(x * CELL + inset, y * CELL + inset, s, s, newborn ? 3 : 2.5);
        else ctx.rect(x * CELL + inset, y * CELL + inset, s, s);
        ctx.fill();
      }
    }

    // hovered cell outline
    if (hover) {
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      if (hasRound) ctx.roundRect(hover.x * CELL + 0.75, hover.y * CELL + 0.75, CELL - 1.5, CELL - 1.5, 3);
      else ctx.rect(hover.x * CELL + 0.75, hover.y * CELL + 0.75, CELL - 1.5, CELL - 1.5);
      ctx.stroke();
    }
  }

  function population() {
    let n = 0;
    for (let i = 0; i < grid.length; i++) n += grid[i];
    return n;
  }

  function updateStats() {
    genEl.textContent = generation;
    popEl.textContent = population();
  }

  /* ================= actions ================= */
  function setCell(x, y, v) {
    if (x < 0 || y < 0 || x >= COLS || y >= ROWS) return;
    const i = idx(x, y);
    if (v) {
      grid[i] = 1;
      if (!age[i]) age[i] = 1;
    } else {
      grid[i] = 0;
      age[i] = 0;
    }
    draw();
    updateStats();
  }

  function clearAll() {
    stopAutoRun();
    grid = new Uint8Array(COLS * ROWS);
    age = new Uint8Array(COLS * ROWS);
    generation = 0;
    draw();
    updateStats();
  }

  function randomize(density) {
    const p = density == null ? 0.28 : density;
    for (let i = 0; i < grid.length; i++) {
      const v = Math.random() < p ? 1 : 0;
      grid[i] = v;
      age[i] = v;
    }
    generation = 0;
    draw();
    updateStats();
  }

  function stepOnce() {
    stopAutoRun();        // a manual step is exactly one generation
    stepGeneration();
  }

  /* ================= auto-run ================= */
  function setPlaying(on) {
    playing = on;
    playBtn.textContent = on ? '⏸ Pause' : '▶ Play';
    playBtn.classList.toggle('is-playing', on);
    playBtn.setAttribute('aria-pressed', String(on));
  }
  function stopAutoRun() { if (playing) setPlaying(false); }
  function toggleAutoRun() { setPlaying(!playing); }

  let lastT = 0, acc = 0;
  function frame(t) {
    if (!lastT) lastT = t;
    const dt = Math.min(0.25, (t - lastT) / 1000);
    lastT = t;
    if (playing) {
      acc += dt;
      const interval = 1 / speed;
      let guard = 0;
      while (acc >= interval && guard < 8) {
        stepGeneration();
        acc -= interval;
        guard++;
      }
      if (acc > interval) acc = interval;
    } else {
      acc = 0;
    }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);

  /* ================= controls ================= */
  document.getElementById('step').addEventListener('click', stepOnce);
  playBtn.addEventListener('click', toggleAutoRun);
  document.getElementById('random').addEventListener('click', () => randomize());
  document.getElementById('clear').addEventListener('click', clearAll);

  speedInput.addEventListener('input', () => {
    speed = Number(speedInput.value) || 1;
    speedVal.textContent = speed + ' gen/s';
  });

  window.addEventListener('keydown', (e) => {
    const t = e.target;
    const tag = t && t.tagName;
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || tag === 'BUTTON' ||
        (t && t.isContentEditable)) return;
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    switch (e.code) {
      case 'Space':
        e.preventDefault();
        if (!e.repeat) toggleAutoRun();
        break;
      case 'KeyS': stepOnce(); break;
      case 'KeyR': randomize(); break;
      case 'KeyC': clearAll(); break;
    }
  });

  /* ================= painting on the grid ================= */
  let painting = false;
  let paintValue = 1;
  let lastPointerDown = -1e9, lastPointerMove = -1e9, lastPointerUp = -1e9;
  let lastDownAny = -1e9, lastUpAny = -1e9;

  function cellFromPoint(cx, cy) {
    const rect = canvas.getBoundingClientRect();
