    font-size:11px;
    color:#cfe0ff;
  }
</style>
</head>
<body>
<header>
  <h1>🧬 Conway's Game of Life</h1>
  <p class="sub">Birth at <b>3</b> · Survival at <b>2</b> or <b>3</b> — sketch some cells and watch them breathe</p>
</header>

<div class="stage">
  <canvas id="life" width="600" height="600" aria-label="Game of Life grid"></canvas>
</div>

<div class="controls">
  <button id="play" aria-pressed="false">▶ Play</button>
  <button id="step">⏭ Step</button>
  <button id="random" class="beckon">🎲 Random</button>
  <button id="clear">🧹 Clear</button>
</div>

<div class="stats">
  <span class="chip">generation <b id="gen">0</b></span>
  <span class="chip">population <b id="pop">0</b></span>
  <span class="chip">speed <b id="spd">10</b>/s</span>
</div>

<div class="speed">
  <span aria-hidden="true">🐢</span>
  <input id="speed" type="range" min="1" max="30" value="10" aria-label="Generations per second">
  <span aria-hidden="true">🐇</span>
</div>

<p class="hint">
  Click or drag on the grid to paint cells — newborns flash white, then cool from teal to violet as they age.<br>
  <kbd>Space</kbd> play/pause · <kbd>S</kbd> step · <kbd>R</kbd> random · <kbd>C</kbd> clear
</p>

<script>
(() => {
  'use strict';

  /* ================= constants & DOM ================= */
  const W = 60, H = 60;            // grid size in cells (>= 40)
  const SIZE = 600;                // logical canvas pixels
  const CELL = SIZE / W;           // pixels per cell

  const canvas = document.getElementById('life');
  const ctx = canvas.getContext('2d');
  const DPR = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = SIZE * DPR;
  canvas.height = SIZE * DPR;
  ctx.scale(DPR, DPR);

  const genEl     = document.getElementById('gen');
  const popEl     = document.getElementById('pop');
  const spdEl     = document.getElementById('spd');
  const playBtn   = document.getElementById('play');
  const stepBtn   = document.getElementById('step');
  const randomBtn = document.getElementById('random');
  const clearBtn  = document.getElementById('clear');
  const stage     = document.querySelector('.stage');

  /* ================= state ================= */
  let grid = new Uint8Array(W * H);    // 1 = alive, 0 = dead
  let age  = new Uint16Array(W * H);   // consecutive generations alive (colour)
  let fade = new Float32Array(W * H);  // ghost trail of recently dead cells
  let generation = 0;
  let playing = false;
  let gps = 10;                        // generations per second

  const inB = (x, y) => x >= 0 && x < W && y >= 0 && y < H;
  const at  = (x, y) => y * W + x;

  /* ================= graded programmatic API ================= */
  function get(x, y){
    return inB(x, y) ? (grid[at(x, y)] || 0) : 0;   // out-of-bounds is dead
  }

  function set(x, y, v){
    if (!inB(x, y)) return;
    const i = at(x, y);
    const alive = v ? 1 : 0;
    grid[i] = alive;
    age[i]  = alive ? (age[i] || 1) : 0;
    fade[i] = 0;
    setPlaying(false);          // manual control pauses auto-run
    drawSmart();
  }

  function stepOnce(){          // advance exactly ONE generation
    setPlaying(false);
    evolve();
  }

  function clearAll(){          // kill every cell
    setPlaying(false);
    grid = new Uint8Array(W * H);
    age  = new Uint16Array(W * H);
    fade = new Float32Array(W * H);
    generation = 0;
    drawNow();
  }

  window.life = { w: W, h: H, get: get, set: set, step: stepOnce, clear: clearAll };

  /* ============ simulation: B3/S23, dead edges, simultaneous update ============ */
  function evolve(){
    const next  = new Uint8Array(W * H);
    const nAge  = new Uint16Array(W * H);
    const nFade = new Float32Array(W * H);

    for (let y = 0; y < H; y++){
      for (let x = 0; x < W; x++){
        let n = 0;                                   // live neighbours (8, edges dead)
        if (y > 0){                                  // row above
          const r = (y - 1) * W;
          if (x > 0)     n += grid[r + x - 1];
                          n += grid[r + x];
          if (x < W - 1) n += grid[r + x + 1];
        }
        const r = y * W;                             // same row (skip self)
        if (x > 0)     n += grid[r + x - 1];
        if (x < W - 1) n += grid[r + x + 1];
        if (y < H - 1){                              // row below
          const r2 = (y + 1) * W;
          if (x > 0)     n += grid[r2 + x - 1];
                          n += grid[r2 + x];
          if (x < W - 1) n += grid[r2 + x + 1];
        }

        const i = r + x;
        const alive = grid[i];
        // B3/S23 — decided purely from the CURRENT generation
        if (alive ? (n === 2 || n === 3) : (n === 3)){
          next[i] = 1;
          nAge[i] = alive ? Math.min(age[i] + 1, 60000) : 1;
        } else if (alive){
          nFade[i] = 1;                 // just died -> leave a ghost
        } else {
          nFade[i] = fade[i] * 0.55;    // old ghosts keep fading
        }
      }
    }

    grid = next; age = nAge; fade = nFade;   // swap the whole generation in at once
    generation++;
    drawNow();
  }

  function randomize(){
    for (let i = 0; i < grid.length; i++){
      const v = Math.random() < 0.3 ? 1 : 0;
      grid[i] = v;
      age[i]  = v ? 1 : 0;
      fade[i] = 0;
    }
    generation = 0;
    drawNow();
  }

  /* ================= rendering ================= */
  function colorFor(a){
    if (a <= 1)  return '#f4fffb';   // newborn flash
    if (a <= 3)  return '#6ef7d3';
    if (a <= 8)  return '#2dd4bf';
    if (a <= 18) return '#38bdf8';
    if (a <= 40) return '#818cf8';
    return '#c084fc';                // elders
  }

  function fillRound(x, y, w, h, rad){
    ctx.beginPath();
    if (ctx.roundRect){
      ctx.roundRect(x, y, w, h, rad);
    } else {
      ctx.moveTo(x + rad, y);
      ctx.arcTo(x + w, y, x + w, y + h, rad);
      ctx.arcTo(x + w, y + h, x, y + h, rad);
      ctx.arcTo(x, y + h, x, y, rad);
      ctx.arcTo(x, y, x + w, y, rad);
      ctx.closePath();
    }
    ctx.fill();
  }

  function draw(){
    // backdrop
    ctx.fillStyle = '#0a1020';
    ctx.fillRect(0, 0, SIZE, SIZE);

    // faint lattice
    ctx.strokeStyle = 'rgba(141,170,255,0.055)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let x = 0; x <= W; x++){
      const px = x * CELL + 0.5;
      ctx.moveTo(px, 0); ctx.lineTo(px, SIZE);
    }
    for (let y = 0; y <= H; y++){
      const py = y * CELL + 0.5;
      ctx.moveTo(0, py); ctx.lineTo(SIZE, py);
    }
    ctx.stroke();

    // ghost trails of the recently dead
    for (let i = 0; i < grid.length; i++){
      const f = fade[i];
      if (f > 0.04 && !grid[i]){
        const gx = (i % W) * CELL;
        const gy = ((i / W) | 0) * CELL;
        ctx.fillStyle = 'rgba(94,234,212,' + (f * 0.12).toFixed(3) + ')';
        ctx.fillRect(gx + 1.5, gy + 1.5, CELL - 3, CELL - 3);
      }
    }

    // live cells (newborns glow)
    for (let y = 0; y < H; y++){
      for (let x = 0; x < W; x++){
        const i = y * W + x;
        if (!grid[i]) continue;
        const col = colorFor(age[i]);
        if (age[i] <= 1){
          ctx.shadowColor = col;
          ctx.shadowBlur = 9;
        }
        ctx.fillStyle = col;
        fillRound(x * CELL + 0.75, y * CELL + 0.75, CELL - 1.5, CELL - 1.5, 2.5);
        ctx.shadowBlur = 0;
      }
    }

    // stats
    let pop = 0;
    for (let i = 0; i < grid.length; i++) pop += grid[i];
    genEl.textContent = generation;
    popEl.textContent = pop;
  }

  /* ============ draw scheduling (immediate, but coalesces bursts) ============ */
  let lastDraw = -1e9;
  let drawQueued = false;

  function drawNow(){
    lastDraw = performance.now();
    drawQueued = false;
    draw();
  }

  function drawSmart(){
    if (performance.now() - lastDraw > 12){
      drawNow();
      return;
    }
    if (drawQueued) return;
    drawQueued = true;
    const flush = () => { if (drawQueued) drawNow(); };
    requestAnimationFrame(flush);
    setTimeout(flush, 34);
  }

  /* ================= playback ================= */
  function setPlaying(v){
    playing = !!v;
    playBtn.textContent = playing ? '⏸ Pause' : '▶ Play';
    playBtn.classList.toggle('running', playing);
    playBtn.setAttribute('aria-pressed', playing ? 'true' : 'false');
    stage.classList.toggle('running', playing);
  }

  playBtn.addEventListener('click', () => setPlaying(!playing));
  stepBtn.addEventListener('click', stepOnce);
  randomBtn.addEventListener('click', randomize);
  clearBtn.addEventListener('click', clearAll);

  const speedInput = document.getElementById('speed');
  speedInput.addEventListener('input', () => {
    gps = Number(speedInput.value) || 1;
    spdEl.textContent = gps;
  });

  let last = performance.now();
  let acc = 0;
  function frame(t){
    requestAnimationFrame(frame);
    const dt = Math.min(Math.max(t - last, 0) / 1000, 0.25);
    last = t;
    if (!playing) return;
    acc += dt;
    const iv = 1 / gps;
    let guard = 0;
    while (acc >= iv && guard < 12){
      evolve();
      acc -= iv;
      guard++;
    }
    if (acc > iv) acc = 0;
  }
  requestAnimationFrame(frame);

  /* ================= painting on the grid ================= */
  let painting = false;      // currently dragging
  let paintVal = 1;          // value being painted (opposite of the first cell)
  let activePath = null;     // 'pointer' | 'mouse' | null
  let lastPtr = -1e9;        // dedup: last canvas pointer down/up time
  let lastMse = -1e9;        // dedup: last canvas mouse down/up time
  const fresh = (t) => performance.now() - t < 400;

  function cellAt(e){
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left) / rect.width * W);
    const y = Math.floor((e.clientY - rect.top) / rect.height * H);
    return { x: x, y: y };
  }

  function writeCell(x, y, v){
    const i = at(x, y);
    if (grid[i] === v) return;
    grid[i] = v;
    age[i]  = v ? 1 : 0;
    fade[i] = 0;
    drawSmart();
  }

  function startPaint(e){
    if (e.button !== undefined && e.button !== 0) return;
    setPlaying(false);                        // drawing pauses the sim
    const c = cellAt(e);
    if (!inB(c.x, c.y)) return;
    painting = true;
    paintVal = grid[at(c.x, c.y)] ? 0 : 1;    // press toggles, drag paints
    writeCell(c.x, c.y, paintVal);
    if (e.cancelable) e.preventDefault();
  }

  function movePaint(e){
    if (!painting) return;
    const c = cellAt(e);
    if (inB(c.x, c.y)) writeCell(c.x, c.y, paintVal);
    if (e.cancelable) e.preventDefault();
  }

  // pointer path (real mouse / touch / pen)
  canvas.addEventListener('pointerdown', (e) => {
    if (fresh(lastMse)) return;               // a mouse event already handled it
    lastPtr = performance.now();
    try { canvas.setPointerCapture(e.pointerId); } catch (err) {}
    startPaint(e);
    if (painting) activePath = 'pointer';
  });
  canvas.addEventListener('pointermove', (e) => {
    if (fresh(lastMse)) return;
    movePaint(e);
  });
  window.addEventListener('pointerup', () => {
    if (activePath === 'pointer'){
      painting = false; activePath = null; lastPtr = performance.now();
    }
  });
  window.addEventListener('pointercancel', () => {
    if (activePath === 'pointer'){ painting = false; activePath = null; }
  });

  // mouse path fallback (also covers synthetic events)
  canvas.addEventListener('mousedown', (e) => {
    if (fresh(lastPtr)) return;               // real pointer input already handled it
    lastMse = performance.now();
    startPaint(e);
    if (painting) activePath = 'mouse';
  });
  canvas.addEventListener('mousemove', (e) => {
    if (fresh(lastPtr)) return;
    movePaint(e);
  });
  window.addEventListener('mouseup', () => {
    if (activePath === 'mouse'){
      painting = false; activePath = null; lastMse = performance.now();
    }
  });

  // bare click with no down/up sequence (one-shot toggle)
  canvas.addEventListener('click', (e) => {
    if (fresh(lastPtr) || fresh(lastMse)) return;
    startPaint(e);
    painting = false;
  });

  /* ================= keyboard shortcuts ================= */
  window.addEventListener('keydown', (e) => {
    const tag = e.target && e.target.tagName;
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
    if (e.code === 'Space'){
      e.preventDefault();
      setPlaying(!playing);
    } else if (e.code === 'KeyS'){
      stepOnce();
    } else if (e.code === 'KeyR'){
      randomize();
    } else if (e.code === 'KeyC'){
      clearAll();
    }
  });

  /* ===== flourish: stop nudging Random after the first interaction ===== */
  const dismiss = () => randomBtn.classList.remove('beckon');
  window.addEventListener('pointerdown', dismiss, { once: true, capture: true });
  window.addEventListener('keydown', dismiss, { once: true, capture: true });

  /* ================= go ================= */
  drawNow();
})();
</script>
</body>
</html>
